final class CaseMaterialRequestsTabController {
    private static final Logger LOG=LoggerFactory.getLogger(CaseMaterialRequestsTabController.class); private static final DateTimeFormatter F=DateTimeFormatter.ofPattern("MMM d, yyyy h:mm a");
    private final ExecutorService ex=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"case-material-requests-worker");t.setDaemon(true);return t;}); private final AtomicInteger gen=new AtomicInteger(); private final AtomicBoolean saving=new AtomicBoolean();
    private MaterialRequestServicePort svc; private AppState state; private Supplier<Long> caseId; private Supplier<Window> owner; private VBox root,list; private Label title,status; private boolean loaded;
    void init(MaterialRequestServicePort s, AppState a, Supplier<Long> c, Supplier<Window> o){svc=s;state=a;caseId=c;owner=o;}
    Node view(){ if(root!=null)return root; list=new VBox(10); title=title("Material Requests"); status=muted("Loading material requests…"); Button add=primary("New Request"); add.setOnAction(e->openEditor(null)); root=new VBox(10,section(title,add,status,list)); root.setPadding(new Insets(8)); root.getStyleClass().add("case-main-surface"); return root; }
    void load(){ if(!loaded) refresh(); } void refresh(){ long cid=cid(); int tid=tenant(); int g=gen.incrementAndGet(); show(status,"Loading material requests…"); list.getChildren().clear(); runRead("list-material-requests",()->svc.listMaterialRequests(cid,tid), rows->{ if(stale(g,cid))return; loaded=true; render(rows==null?List.of():rows);}, "Material requests could not be loaded."); }
    private void render(List<MaterialRequestSummaryDto> rows){ var sorted=rows.stream().sorted(Comparator.comparing((MaterialRequestSummaryDto r)->terminal(r.status())).thenComparing(r->Optional.ofNullable(r.nextFollowUpAt()).orElse(Optional.ofNullable(r.expectedResponseDate()).orElse(LocalDateTime.MAX))).thenComparingLong(MaterialRequestSummaryDto::id)).toList(); title.setText("Material Requests ("+sorted.size()+")"); list.getChildren().clear(); if(sorted.isEmpty())show(status,"No material requests yet."); else {hide(status); sorted.forEach(r->list.getChildren().add(card(r)));}}
    private Node card(MaterialRequestSummaryDto r){ VBox b=MaterialsUi.card(); b.getChildren().addAll(strong(nvl(r.title(),r.materialTypeName())), pill("Status: "+nvl(r.status(),"Unknown")), line("From",source(r.requestedFromContactDisplayName(),r.requestedFromOrganizationName(),r.requestedFromText())), line("Assigned",nvl(r.assignedToDisplayName(),"Unassigned")), line("Requested / Due / Follow-up",fmt(r.requestedAt())+" • Due "+fmt(r.expectedResponseDate())+" • Next "+fmt(r.nextFollowUpAt()))); b.setOnMouseClicked(e->openDetail(r.id())); return b; }
    private void openDetail(long id){ long c=cid(); int t=tenant(), a=actor(); runRead("get-material-request",()->svc.getMaterialRequest(c,id,t,a).orElseThrow(),this::detail,"Material request could not be loaded."); }
    private void detail(MaterialRequestDetailDto d){ Dialog<Void> dlg=dialog("Material Request"); VBox c=new VBox(10,strong(nvl(d.title(),d.materialTypeName())),line("Status",nvl(d.status(),"Unknown")),line("Source",source(d.requestedFromContactDisplayName(),d.requestedFromOrganizationName(),d.requestedFromText())),line("Dates",fmt(d.requestedAt())+" • Due "+fmt(d.expectedResponseDate())+" • Follow-up "+fmt(d.nextFollowUpAt())),text("Description",d.description()),text("Notes",d.notes())); ButtonType follow=new ButtonType("Record Follow-up"), edit=new ButtonType("Edit"), statusBt=new ButtonType("Change Status"), del=new ButtonType("Delete", ButtonBar.ButtonData.LEFT); dlg.getDialogPane().getButtonTypes().addAll(follow,edit,statusBt,del,ButtonType.CLOSE); dlg.getDialogPane().setContent(new ScrollPane(c)); button(dlg,follow,()->follow(d)); button(dlg,edit,()->openEditor(d)); button(dlg,statusBt,()->changeStatus(d)); button(dlg,del,()->delete(d)); dlg.showAndWait(); }
    private void openEditor(MaterialRequestDetailDto e){ MaterialRequestForm f=new MaterialRequestForm(e, svc.listEffectiveMaterialTypes(tenant()), actor()); Optional<MaterialRequestForm.Values> v=f.showAndWait(); v.ifPresent(x->mutate(()-> e==null?svc.createMaterialRequest(x.create(tenant(),actor(),cid())):svc.updateMaterialRequest(x.update(tenant(),actor(),cid(),e.id(),e.rowVer())), this::refresh, "Material request saved.")); }
    private void follow(MaterialRequestDetailDto d){ TextInputDialog t=new TextInputDialog(); t.setTitle("Record Follow-up"); t.setHeaderText("Append-only follow-up history. Existing follow-ups cannot be edited or deleted."); t.showAndWait().ifPresent(note->mutate(()->svc.recordFollowUp(new MaterialRequestServicePort.RecordMaterialRequestFollowUpCommand(tenant(),actor(),cid(),d.id(),LocalDateTime.now(),actor(),"PHONE","NO_RESPONSE",d.nextFollowUpAt(),trim(note),d.rowVer())),this::refresh,"Follow-up recorded."));}
    private void changeStatus(MaterialRequestDetailDto d){ ChoiceDialog<String> c=new ChoiceDialog<>(d.status(),List.of("DRAFT","REQUESTED","FOLLOW_UP_DUE","PARTIALLY_RECEIVED","FULLY_RECEIVED","CLOSED","CANCELLED")); c.setTitle("Change Request Status"); c.showAndWait().ifPresent(s->mutate(()->svc.changeMaterialRequestStatus(new MaterialRequestServicePort.ChangeMaterialRequestStatusCommand(tenant(),actor(),cid(),d.id(),s,d.requestedAt(),d.firstReceivedAt(),d.fullyReceivedAt(),LocalDateTime.now(),actor(),d.closureReason(),d.rowVer())),this::refresh,"Request status changed."));}
    private void delete(MaterialRequestDetailDto d){ mutate(()->{svc.deleteMaterialRequest(new MaterialRequestServicePort.DeleteMaterialRequestCommand(tenant(),actor(),cid(),d.id(),d.rowVer()));return null;},this::refresh,"Request deleted.");}
    private <T>void runRead(String op,Supplier<T>w,java.util.function.Consumer<T>ok,String msg){ ex.submit(()->{try{T t=w.get();Platform.runLater(()->ok.accept(t));}catch(Exception x){LOG.warn("Case Materials read failed op={} caseId={} generation={}",op,cid(),gen.get(),x);Platform.runLater(()->showInlineError(msg));}});} private void showInlineError(String m){list.getChildren().clear(); Button r=new Button("Retry"); r.setOnAction(e->refresh()); show(status,m); list.getChildren().add(r); AppDialogs.showError(owner.get(),"Requests",m);} private <T>void mutate(Supplier<T>w,Runnable after,String msg){ if(!saving.compareAndSet(false,true))return; ex.submit(()->{try{w.get();Platform.runLater(()->{saving.set(false);after.run();AppDialogs.showInfo(owner.get(),"Requests",msg);});}catch(Exception x){LOG.warn("Case material request mutation failed caseId={}",cid(),x);Platform.runLater(()->{saving.set(false);AppDialogs.showError(owner.get(),"Requests",friendly(x));});}});} private boolean stale(int g,long c){return g!=gen.get()||cid()!=c;} private long cid(){return caseId.get();} private int tenant(){return state.getShaleClientId();} private int actor(){Integer i=state.getUserId();return i==null?0:i;}
    private static boolean terminal(String s){return Set.of("CLOSED","CANCELLED","FULLY_RECEIVED").contains(nvl(s,"").toUpperCase(Locale.ROOT));} static String friendly(Exception x){String m=String.valueOf(x.getMessage()).toLowerCase(Locale.ROOT);return m.contains("rowver")||m.contains("concurr")?"This record changed by another user. Reload and try again.":"The request could not be saved. Please review the fields and try again.";}
}

final class CaseMaterialItemsTabController {
    private static final Logger LOG=LoggerFactory.getLogger(CaseMaterialItemsTabController.class); private final ExecutorService ex=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"case-material-items-worker");t.setDaemon(true);return t;}); private final AtomicInteger gen=new AtomicInteger(); private final AtomicBoolean saving=new AtomicBoolean(); private MaterialRequestServicePort req; private MaterialItemServicePort svc; private AppState state; private Supplier<Long> caseId; private Supplier<Window> owner; private VBox root,list; private Label title,status; private volatile List<MaterialRequestSummaryDto> activeRequests=List.of(); private boolean loaded;
    void init(MaterialRequestServicePort r,MaterialItemServicePort s,AppState a,Supplier<Long> c,Supplier<Window> o){req=r;svc=s;state=a;caseId=c;owner=o;} Node view(){if(root!=null)return root; list=new VBox(10); title=title("Case Materials"); status=muted("Loading case materials…"); Button add=primary("New Material"); add.setOnAction(e->openEditor(null)); root=new VBox(10,section(title,add,status,list)); root.setPadding(new Insets(8)); root.getStyleClass().add("case-main-surface"); return root;} void load(){if(!loaded)refresh();} void refresh(){long c=cid();int t=tenant();int g=gen.incrementAndGet();show(status,"Loading case materials…");list.getChildren().clear();runRead("list-material-items",()->{activeRequests=req.listMaterialRequests(c,t).stream().filter(r->!Set.of("CLOSED","CANCELLED").contains(nvl(r.status(),"").toUpperCase(Locale.ROOT))).toList();return svc.listMaterialItems(c,t);}, rows->{if(stale(g,c))return;loaded=true;render(rows==null?List.of():rows);},"Case materials could not be loaded.");}
    private void render(List<MaterialItemSummaryDto> rows){var sorted=rows.stream().sorted(Comparator.comparing((MaterialItemSummaryDto i)->Optional.ofNullable(i.receivedAt()).orElse(LocalDateTime.MIN),Comparator.reverseOrder()).thenComparing(i->nvl(i.name(),""),String.CASE_INSENSITIVE_ORDER)).toList(); title.setText("Case Materials ("+sorted.size()+")"); list.getChildren().clear(); if(sorted.isEmpty())show(status,"No case materials yet."); else{hide(status);sorted.forEach(i->list.getChildren().add(card(i)));}}
    private Node card(MaterialItemSummaryDto i){VBox b=MaterialsUi.card();b.getChildren().addAll(strong(nvl(i.name(),i.materialTypeName())),pill("Custody: "+nvl(i.custodyStatus(),"Unknown")),line("Format",nvl(i.format(),"Unknown")+" • "+nvl(i.completeness(),"Completeness unknown")),line("Received",fmt(i.receivedAt())+" by "+nvl(i.receivedByDisplayName(),"Unknown")),line("Counts","Qty "+val(i.quantityCount())+" • Pages "+val(i.pageCount())+" • Files "+val(i.fileCount())+(i.materialRequestId()!=null?" • Linked to request":" • No request link"))); b.setOnMouseClicked(e->openDetail(i.id()));return b;}
    private void openDetail(long id){runRead("get-material-item",()->svc.getMaterialItem(cid(),id,tenant(),actor()).orElseThrow(),this::detail,"Case material could not be loaded.");} private void detail(MaterialItemDetailDto d){Dialog<Void> dlg=dialog("Case Material"); VBox c=new VBox(10,strong(nvl(d.name(),d.materialTypeName())),line("Type / format",d.materialTypeName()+" • "+nvl(d.format(),"Unknown")),line("Source",source(d.sourceContactDisplayName(),d.sourceOrganizationName(),d.sourceText())),line("Coverage",fmt(d.relevantStartDate())+" to "+fmt(d.relevantEndDate())),line("Location/reference",nvl(d.storageLocation(),"Not provided")+(d.externalLinkId()!=null?" • ExternalLink reference":"")),line("Custody",nvl(d.custodyStatus(),"Unknown")),text("Description",d.description()),text("Physical condition",d.physicalCondition()),text("Return/release notes",d.returnReleaseNotes())); ButtonType edit=new ButtonType("Edit Metadata"),link=new ButtonType("Link/Unlink Request"),loc=new ButtonType("Location/Reference"),rel=new ButtonType("Record Return/Release"),del=new ButtonType("Delete",ButtonBar.ButtonData.LEFT); dlg.getDialogPane().getButtonTypes().addAll(edit,link,loc,rel,del,ButtonType.CLOSE); dlg.getDialogPane().setContent(new ScrollPane(c)); button(dlg,edit,()->openEditor(d)); button(dlg,link,()->link(d)); button(dlg,loc,()->loc(d)); button(dlg,rel,()->release(d)); button(dlg,del,()->del(d)); dlg.showAndWait();}
    private void openEditor(MaterialItemDetailDto e){MaterialItemForm f=new MaterialItemForm(e,req.listEffectiveMaterialTypes(tenant()),activeRequests,actor());f.showAndWait().ifPresent(v->mutate(()->e==null?svc.createMaterialItem(v.create(tenant(),actor(),cid())):svc.updateMaterialItem(v.update(tenant(),actor(),cid(),e.id(),e.rowVer())),this::refresh,"Material item saved."));}
    private void link(MaterialItemDetailDto d){ if(d.materialRequestId()!=null)mutate(()->svc.unlinkMaterialItemFromRequest(new MaterialItemServicePort.UnlinkMaterialItemFromRequestCommand(tenant(),actor(),cid(),d.id(),d.rowVer())),this::refresh,"Request link removed."); else if(!activeRequests.isEmpty())mutate(()->svc.linkMaterialItemToRequest(new MaterialItemServicePort.LinkMaterialItemToRequestCommand(tenant(),actor(),cid(),d.id(),activeRequests.get(0).id(),d.rowVer())),this::refresh,"Request linked.");}
    private void loc(MaterialItemDetailDto d){TextInputDialog t=new TextInputDialog(nvl(d.storageLocation(),""));t.setTitle("Location/reference metadata");t.setHeaderText("Metadata only. No upload, download, file chooser, attachment, image text extraction, blob-storage, or file storage occurs.");t.showAndWait().ifPresent(s->mutate(()->svc.changeMaterialItemLocation(new MaterialItemServicePort.ChangeMaterialItemLocationCommand(tenant(),actor(),cid(),d.id(),trim(s),d.externalLinkId(),d.rowVer())),this::refresh,"Location metadata updated."));} private void release(MaterialItemDetailDto d){ChoiceDialog<String> c=new ChoiceDialog<>("RETURNED",List.of("RETURNED","RELEASED","DESTROYED"));c.setTitle("Record Return/Release");c.showAndWait().ifPresent(s->mutate(()->svc.releaseOrReturnMaterialItem(new MaterialItemServicePort.ReleaseOrReturnMaterialItemCommand(tenant(),actor(),cid(),d.id(),s,LocalDateTime.now(),null,null,"recipient","HAND_DELIVERY",null,d.rowVer())),this::refresh,"Return/release recorded."));} private void del(MaterialItemDetailDto d){mutate(()->{svc.softDeleteMaterialItem(new MaterialItemServicePort.SoftDeleteMaterialItemCommand(tenant(),actor(),cid(),d.id(),d.rowVer()));return null;},this::refresh,"Material item deleted.");}
    private <T>void runRead(String op,Supplier<T>w,java.util.function.Consumer<T>ok,String msg){ex.submit(()->{try{T t=w.get();Platform.runLater(()->ok.accept(t));}catch(Exception x){LOG.warn("Case Materials read failed op={} caseId={} generation={}",op,cid(),gen.get(),x);Platform.runLater(()->{list.getChildren().clear();Button r=new Button("Retry");r.setOnAction(e->refresh());show(status,msg);list.getChildren().add(r);AppDialogs.showError(owner.get(),"Case Materials",msg);});}});} private <T>void mutate(Supplier<T>w,Runnable after,String msg){if(!saving.compareAndSet(false,true))return;ex.submit(()->{try{w.get();Platform.runLater(()->{saving.set(false);after.run();AppDialogs.showInfo(owner.get(),"Case Materials",msg);});}catch(Exception x){LOG.warn("Case material item mutation failed caseId={}",cid(),x);Platform.runLater(()->{saving.set(false);AppDialogs.showError(owner.get(),"Case Materials","The case material could not be saved. Please review the fields and try again.");});}});} private boolean stale(int g,long c){return g!=gen.get()||cid()!=c;} private long cid(){return caseId.get();} private int tenant(){return state.getShaleClientId();} private int actor(){Integer i=state.getUserId();return i==null?0:i;}
}

