final class MaterialsUi { private MaterialsUi(){}
    static Label title(String s){Label l=new Label(s);l.setStyle("-fx-font-size:16px;-fx-font-weight:bold;");return l;} static Label strong(String s){Label l=new Label(s);l.setStyle("-fx-font-weight:bold;");l.setWrapText(true);return l;} static Label muted(String s){Label l=new Label(s);l.setStyle("-fx-opacity:.75;");l.setWrapText(true);return l;} static Label pill(String s){Label l=new Label(s);l.getStyleClass().add("shale-status-pill");return l;} static Label line(String k,String v){Label l=new Label(k+": "+v);l.setWrapText(true);return l;} static Label text(String k,String v){return line(k,nvl(v,"Not provided"));} static Button primary(String s){Button b=new Button(s);b.getStyleClass().addAll("app-toolbar-button","app-toolbar-button-primary");return b;} static VBox card(){VBox v=new VBox(6);v.setPadding(new Insets(10));v.getStyleClass().addAll("shale-card","entity-card");return v;} static VBox section(Label t,Button b,Label s,VBox list){HBox h=new HBox(8,t,new Region(),b);HBox.setHgrow(h.getChildren().get(1),Priority.ALWAYS);h.setAlignment(Pos.CENTER_LEFT);ScrollPane sp=new ScrollPane(list);sp.setFitToWidth(true);VBox v=new VBox(10,h,s,sp);VBox.setVgrow(sp,Priority.ALWAYS);v.setPadding(new Insets(10));v.getStyleClass().add("shale-surface-section");return v;} static void show(Label l,String s){l.setText(s);l.setVisible(true);l.setManaged(true);} static void hide(Label l){l.setVisible(false);l.setManaged(false);} static Dialog<Void> dialog(String t){Dialog<Void>d=new Dialog<>();d.setTitle(t);d.getDialogPane().setPrefSize(720,620);return d;} static void button(Dialog<?>d,ButtonType t,Runnable r){Node n=d.getDialogPane().lookupButton(t);n.addEventFilter(javafx.event.ActionEvent.ACTION,e->{e.consume();r.run();});} static String trim(String s){return s==null?null:s.trim();} static String nvl(String s,String v){return s==null||s.isBlank()?v:s;} static String fmt(LocalDateTime t){return t==null?"Not set":t.format(DateTimeFormatter.ofPattern("MMM d, yyyy h:mm a"));} static String fmt(LocalDate d){return d==null?"Not set":d.toString();} static String source(String c,String o,String t){return nvl(c,nvl(o,nvl(t,"Not provided")));} static String val(Object o){return o==null?"—":o.toString();} static Integer num(TextField f){try{String s=f.getText();return s==null||s.isBlank()?null:Integer.valueOf(s.trim());}catch(Exception e){return null;}} static Integer nonneg(TextField f){Integer n=num(f);return n==null?null:Math.max(0,n);} static LocalDateTime at(LocalDate d){return d==null?null:d.atStartOfDay();} static LocalDate toDate(LocalDateTime d){return d==null?null:d.toLocalDate();} static GridPane grid(){GridPane g=new GridPane();g.setHgap(10);g.setVgap(8);g.setPadding(new Insets(12));return g;} static void add(GridPane g,int r,String label,Node n){g.add(new Label(label),0,r);g.add(n,1,r);}
}
